$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
$p=new PDO('mysql:host='.$env['GPT_DB_HOST'].';port='.$env['GPT_DB_PORT'].';dbname=gatlas_dbp;charset=utf8mb4',$env['GPT_DB_USERNAME'],$env['GPT_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$tables=$p->query("SELECT table_name FROM information_schema.tables WHERE table_schema='gatlas_dbp' AND table_type='BASE TABLE' AND table_collation<>'utf8mb4_0900_ai_ci'")->fetchAll(PDO::FETCH_COLUMN);$ok=[];$failed=[];foreach($tables as $table){try{$p->exec('ALTER TABLE `'.$table.'` ENGINE=InnoDB, ROW_FORMAT=DYNAMIC, CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci');$ok[]=$table;}catch(Throwable $e){$failed[$table]=$e->getMessage();}}
